"""Writes the gamepad layout-family pictures (batch 11, roadmap F-42) as
HVIF vector icons into src/preferences/gamepads/GamepadLayouts.rdef:

    3rdparty/ce/tools/make_gamepad_layout_icons.py > \\
        src/preferences/gamepads/GamepadLayouts.rdef
    3rdparty/ce/tools/make_gamepad_layout_icons.py --preview sheet.png

One picture per layout family, by the features that tell them apart and
never a vendor's shape or logo: "offset" (D-pad below the left stick, as
Xbox-style and Nintendo-style pads), "symmetric" (both sticks below, as
PlayStation-style pads), "nintendo" (offset, with the Nintendo face order
marked by a gold east button), "retro" (an oval SNES-style pad without
sticks), "generic" (a plain pad, numbered buttons) and "arcade" (a fight
stick: a ball-top lever and eight buttons). Resources 'VICN' 1001-1006,
named "layout:<family>"; Gamepads and gamepad_agent load them by name.
The style follows the Gamepads icon (make_gamepads_icon.py): the Renga
leaf green body, dark controls, orange and gold accents, dark outlines.
"""

import math
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import hvif
from make_gamepads_icon import (GREEN, ORANGE, GOLD, BODY, BODY_SIDE,
	OUTLINE, DARK, tilt, ellipse, body_outline)

FAMILIES = ["offset", "symmetric", "nintendo", "retro", "generic", "arcade"]
GREY = ((200, 204, 210, 255), (130, 136, 146, 255))


def fill(colours, box):
	(x0, y0), (x1, y1) = box
	return hvif.gradient((x0, y0), (x1, y1), [(0, colours[0]),
		(255, colours[1])])


def pad_body(icon, colours=BODY):
	top = tilt(body_outline())
	icon.polygon([(x, y + 5) for x, y in top], fill(BODY_SIDE,
		((8, 40), (56, 60))), outline=(OUTLINE, 3))
	icon.polygon(top, fill(colours, ((10, 14), (50, 52))),
		outline=(OUTLINE, 3))


def dpad(icon, cx, cy):
	cross = [(cx - 6, cy - 2), (cx - 2, cy - 2), (cx - 2, cy - 6),
		(cx + 2, cy - 6), (cx + 2, cy - 2), (cx + 6, cy - 2), (cx + 6, cy + 2),
		(cx + 2, cy + 2), (cx + 2, cy + 6), (cx - 2, cy + 6), (cx - 2, cy + 2),
		(cx - 6, cy + 2)]
	icon.polygon(tilt(cross), fill(DARK, ((cx - 5, cy - 5), (cx + 5,
		cy + 5))))


def stick(icon, cx, cy):
	icon.polygon(tilt(ellipse(cx, cy, 4.2, 4.2)), fill(DARK, ((cx - 3,
		cy - 3), (cx + 3, cy + 3))), outline=(OUTLINE, 2))


def face(icon, colours=(GOLD, ORANGE, ORANGE, GOLD), cx=46, cy=26):
	# north, west, east, south
	for (x, y), colour in zip(((cx, cy - 5), (cx - 4, cy), (cx + 4, cy),
			(cx, cy + 5)), colours):
		icon.polygon(tilt(ellipse(x, y, 2.6, 2.6, 12)), fill(colour,
			((x - 2, y - 2), (x + 2, y + 2))))


def build(family):
	icon = hvif.Icon()
	if family == "arcade":
		# a box seen from the front-top, a lever and two rows of buttons
		top = [(6, 22), (58, 22), (60, 44), (4, 44)]
		icon.polygon([(x, y + 7) for x, y in top], fill(BODY_SIDE,
			((4, 40), (60, 52))), outline=(OUTLINE, 3))
		icon.polygon(top, fill(BODY, ((6, 22), (58, 44))),
			outline=(OUTLINE, 3))
		icon.polygon([(15, 34), (18, 34), (18, 20), (15, 20)], fill(DARK,
			((14, 20), (19, 34))))
		icon.polygon(ellipse(16.5, 18, 5, 5), fill(ORANGE, ((12, 13),
			(21, 23))), outline=(OUTLINE, 2))
		for row, y in enumerate((28, 36)):
			for i, x in enumerate((31, 38, 45, 52)):
				colour = GOLD if (row + i) % 2 == 0 else ORANGE
				icon.polygon(ellipse(x - row * 1.5, y, 2.6, 2.2, 12),
					fill(colour, ((x - 3, y - 3), (x + 3, y + 3))))
		return icon
	if family == "retro":
		top = tilt(hvif.arc_points(18, 30, 12, 90, 270, 10)
			+ hvif.arc_points(46, 30, 12, -90, 90, 10))
		icon.polygon([(x, y + 5) for x, y in top], fill(BODY_SIDE,
			((8, 40), (56, 60))), outline=(OUTLINE, 3))
		icon.polygon(top, fill(BODY, ((10, 18), (54, 44))),
			outline=(OUTLINE, 3))
		dpad(icon, 18, 30)
		face(icon, cx=46, cy=30)
		return icon

	pad_body(icon, GREY if family == "generic" else BODY)
	if family == "symmetric":
		dpad(icon, 19, 27)
		stick(icon, 25, 37)
		stick(icon, 39, 37)
	else:
		# offset: the left stick up, the D-pad below it
		stick(icon, 19, 25)
		dpad(icon, 26, 37)
		stick(icon, 39, 37)
	if family == "nintendo":
		# the east button gold: A on the right, as Nintendo pads have it
		face(icon, (ORANGE, ORANGE, GOLD, ORANGE))
	elif family == "generic":
		face(icon, (DARK, DARK, DARK, DARK))
	else:
		face(icon)
	icon.polygon(tilt(ellipse(32, 24, 2.4, 2.4, 12)), fill(ORANGE,
		((30, 22), (34, 26))))
	return icon


def rdef():
	lines = ["/*", " * Copyright 2026, Renga contributors.",
		" * Distributed under the terms of the MIT License.", " *",
		" * The gamepad layout-family pictures. Generated by",
		" * 3rdparty/ce/tools/make_gamepad_layout_icons.py; see there.",
		" */", ""]
	for number, family in enumerate(FAMILIES, 1001):
		lines.append(hvif.rdef_array(number, "layout:" + family,
			build(family).flat()))
		lines.append("")
	return "\n".join(lines)


if __name__ == "__main__":
	if len(sys.argv) == 3 and sys.argv[1] == "--preview":
		from PIL import Image
		sheet = Image.new("RGBA", (len(FAMILIES) * 72 + 8, 120),
			(216, 216, 216, 255))
		for i, family in enumerate(FAMILIES):
			icon = build(family)
			sheet.paste(icon.preview(64, (216, 216, 216, 255)),
				(8 + i * 72, 4))
			sheet.paste(icon.preview(32, (216, 216, 216, 255)),
				(8 + i * 72, 76))
		sheet.save(sys.argv[2])
	else:
		print(rdef(), end="")
